{
	"name": "opencode-session-changes",
	"version": "1.0.0",
	"description": "OpenCode CLI plugin: changed files with per-file +/- line counts in the session sidebar",
	"type": "module",
	"license": "MIT",
	"exports": {
		".": "./index.ts",
		"./tui": "./tui.tsx"
	},
	"files": [
		"index.ts",
		"tui.tsx",
		"README.md",
		"LICENSE"
	],
	"keywords": [
		"opencode",
		"opencode-plugin",
		"tui",
		"diff",
		"git",
		"sidebar"
	],
	"repository": {
		"type": "git",
		"url": "git+https://github.com/kdbsoft/opencode-session-changes.git"
	},
	"homepage": "https://github.com/kdbsoft/opencode-session-changes#readme",
	"bugs": {
		"url": "https://github.com/kdbsoft/opencode-session-changes/issues"
	},
	"scripts": {
		"typecheck": "tsc --noEmit"
	},
	"dependencies": {
		"@opencode/plugin": "^2.0.28"
	},
	"peerDependencies": {
		"@opentui/core": ">=0.5.17",
		"@opentui/solid": ">=0.5.17",
		"solid-js": ">=1.9.0"
	},
	"peerDependenciesMeta": {
		"@opentui/core": {
			"optional": true
		},
		"@opentui/solid": {
			"optional": true
		},
		"solid-js": {
			"optional": true
		}
	},
	"devDependencies": {
		"@opencode/theme": "2.0.28",
		"@opentui/core": "0.5.17",
		"@opentui/solid": "0.5.17",
		"solid-js": "1.9.12",
		"typescript": "5.8.2"
	}
}
